class Solution {
  public int badSensor(int[] sensor1, int[] sensor2) {
    int n = sensor1.length, i = 0;
    while (i < n && sensor1[i] == sensor2[i]) i++;
    if (i >= n - 1) return -1; // identical, or only the last value differs: undecidable
    // if sensor 2 dropped data[i], then sensor2[k] == sensor1[k + 1] from i on (and vice versa)
    boolean twoDropped = true, oneDropped = true;
    for (int k = i; k < n - 1; k++) {
      if (sensor2[k] != sensor1[k + 1]) twoDropped = false;
      if (sensor1[k] != sensor2[k + 1]) oneDropped = false;
    }
    if (twoDropped == oneDropped) return -1;
    return twoDropped ? 2 : 1;
  }
}
